        /// <summary>
        /// Приводит справочники базы к эталону <see cref="Items"/> одной транзакцией:
        /// добавляет недостающие записи, обновляет подписи, удаляет записи, которых нет в эталоне.
        /// Раньше категория заполнялась, только если была пустой, и исправления в коде не доходили до существующих баз.
        /// </summary>
        public static async Task FillingDataBaseAsync()
        {
            using (var uow = new UnitOfWork(Session.DataLayer))
            {
                var existing = await new XPQuery<GeneralizedDictionaryXPO>(uow).ToListAsync();
                SynchronizeDictionary(uow, existing);
                await uow.CommitChangesAsync();
            }
        }

        /// <summary>
        /// Синхронизация справочника с эталоном в рамках переданной сессии (без сохранения).
        /// </summary>
        internal static void SynchronizeDictionary(Session session, IEnumerable<GeneralizedDictionaryXPO> existing)
        {
            var reference = Items.ToDictionary(item => (item.Dictionary, item.Value), item => item.Name);
            var found = new HashSet<(GeneralizedDictionary, string)>();

            foreach (var row in existing.ToList())
            {
                var key = (row.GeneralizedDictionary ?? default, row.Value);
                if (row.GeneralizedDictionary is null || !reference.TryGetValue(key, out var name) || !found.Add(key))
                {
                    // Записи нет в эталоне (устаревший код) или это повтор: такой код не соответствует схеме.
                    row.Delete();
                    continue;
                }

                if (row.Name != name)
                {
                    row.Name = name;
                    session.Save(row);
                }
            }

            foreach (var item in Items)
            {
                if (!found.Contains((item.Dictionary, item.Value)))
                {
                    new GeneralizedDictionaryXPO(session)
                    {
                        GeneralizedDictionary = item.Dictionary,
                        Value = item.Value,
                        Name = item.Name
                    };
                }
            }
        }
    }
